import sys

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    A = list(map(int, input().split()))
    B = list(map(int, input().split()))

    left = []
    j = 0
    for i, x in enumerate(A):
        if j < M and x == B[j]:
            left.append(i)
            j += 1
            if j == M:
                break

    if len(left) < M:
        print("No")
        return

    right = [0] * M
    j = M - 1
    for i in range(N - 1, -1, -1):
        if j >= 0 and A[i] == B[j]:
            right[j] = i
            j -= 1
            if j < 0:
                break

    print("Yes" if left != right else "No")

if __name__ == "__main__":
    main()

